-- ============================================================
-- 八朔・事始め（テーマID: 26, category_id: 4）問題投入SQL
-- 全20問（難易度1〜3）
-- 選択肢対応: (ア)=0, (イ)=1, (ウ)=2, (エ)=3
-- ============================================================

INSERT INTO questions (category_id, theme_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty_level, is_premium) VALUES

(4, 26, '京都の花街で行われる「八朔（はっさく）」の月日として正しいのはどれか。', '1月1日', '8月1日', '12月13日', '8月16日', 1, '花街の「八朔（はっさく）」は、旧暦の8月1日にちなみ毎年8月1日に行われます。芸妓や舞妓が黒紋付の正装で、日頃お世話になっているお茶屋や師匠宅にあいさつ回りをする伝統行事です。', 1, false),
(4, 26, '京都で正月の準備を始める「事始め（ことはじめ）」の日として正しいのはどれか。', '12月1日', '12月13日', '12月25日', '1月4日', 1, '「事始め（ことはじめ）」は毎年12月13日に行われます。この日から正月を迎える準備（煤払いなど）を本格的に始め、祇園などの花街ではお師匠さんやお茶屋へあいさつ回りを行います。', 1, false),
(4, 26, '八朔（8月1日）に花街の芸妓・舞妓が着用する正装の着物はどれか。', '浴衣', '黒紋付（くろもんつき）の着物', '振袖', '訪問着', 1, '八朔の日、芸妓や舞妓は真夏の暑い時期にもかかわらず、紋付の正装である「黒紋付（くろもんつき）」に身を包んであいさつ回りをします。', 1, false),
(4, 26, '「事始め」の日に祇園の井上流お師匠さんの家などへ挨拶に伺う際、持参する伝統的な贈り物はどれか。', '鏡餅', 'お屠蘇', '干支の飾棚・お餅', 'お年玉', 0, '事始めの日、舞妓や芸妓はお師匠さんの家を訪れ、「おめでとうさんどす」と挨拶して鏡餅を贈ります。師匠宅には舞妓たちが持参した鏡餅が段状にずらりと並びます。', 2, false),
(4, 26, '八朔（旧暦8月1日）の本来の語源・歴史的意味として正しいのはどれか。', '八月作物の実りを祝い日頃の恩人に感謝する日', '釈迦の誕生を祝う日', '八坂神社の祭礼日', '八月最初の新月の日', 0, '八朔は「八月朔日（はちがつさくじつ）」の略で、元来は早稲（わせ）の穂を摘んで日頃お世話になっている人に贈る農耕儀礼が始まりです。徳川家康が江戸城に入城した日（八朔）としても知られます。', 2, false),
(4, 26, '祇園甲部の舞の流派で、事始めに師匠宅で鏡餅が重ねられる家元はだれか。', '尾上菊之丞', '井上八千代', '藤間勘十郎', '花柳壽輔', 1, '祇園甲部の舞踊は「京舞井上流（いのうえりゅう）」であり、代々「井上八千代」を名乗ります。事始めの12月13日には、井上八千代師匠の家に大勢の芸舞妓が集まります。', 2, false),
(4, 26, '事始めの日に行われる、神社仏閣で1年の煤やホコリを払い落とす行事は何か。', '煤払い（すすはらい）', '大掃除', '夏越祓', '神輿洗い', 0, '12月13日の事始めには、東西本願寺や祇園八坂神社など市内の寺社で竹笹などを使った「煤払い（すすはらい）」が行われ、正月を迎える清めが行われます。', 1, false),
(4, 26, '八朔の日に、祇園などの街頭で見られる風景として特徴的なものはどれか。', '水かけ祭り', '黒紋付姿の芸舞妓が石畳を移動する姿', '松明を持って練り歩く行列', 'おみこしの巡行', 1, '八朔の日には、黒紋付姿の芸妓・舞妓が「おたのもうします」と声を掛け合いながら祇園の石畳を行き交います。カメラマンや観光客が数多く集まる夏の京都の風物詩です。', 1, false),
(4, 26, '京都の花街で、事始めの日に舞妓たちがお師匠さんから受け取る正月用の飾り物はどれか。', '扇子', '舞扇・かざり扇', '千両箱', '福玉・舞扇', 1, '事始めの日、あいさつに訪れた弟子たちに対してお師匠さんからお年玉や「舞扇（まいおうぎ）」などが手渡され、新年に向けた気持ちを新たにします。', 2, false),
(4, 26, '「こと始め」から正月準備を始める風習は、いつ頃の時代に定着したとされるか。', '平安時代', '鎌倉時代', '江戸時代', '明治時代', 2, '12月13日を「事始め」として正月準備を始める風習は、江戸時代に定着しました。婚礼や家建てなどの吉日とされる「鬼宿日（きしゅくにち）」に由来するとも言われます。', 2, false),
(4, 26, '祇園の南座で12月に行われる、芸舞妓も観客として訪れる伝統芸能公演はどれか。', '都をどり', '吉例顔見世興行（かおみせ）', '祇園コーナー公演', '平成中村座', 1, '12月に南座で行われる「吉例顔見世興行（かおみせ）」は、京都の冬の風物詩です。花街の芸舞妓が総見（そうけん）として揃って観劇に訪れる華やかな光景が見られます。', 1, false),
(4, 26, '顔見世興行の際、南座のまねき看板に飾られる花街の芸舞妓からの贈り物はどれか。', 'まねき猫', '竹の笹飾り', '福玉', '花かんざし', 3, '12月の顔見世興行の時期、舞妓さんは「まねき」と呼ばれる歌舞伎役者の名前が書かれた看板を模した特別な「花かんざし（まねきのかんざし）」を髪に挿します。', 2, false),
(4, 26, '事始め以降、祇園のお茶屋や芸舞妓の家々の軒先に飾られる球体の飾り物はどれか。', '福玉（ふくだま）', 'くす玉', '吊るし雛', '提灯', 0, '「福玉（ふくだま）」は紅白の最中（もなか）地に縁起物の玩具が入った球体の飾りで、事始めの頃からお茶屋などに飾られ、除夜の鐘を聞いた後に割って中身を確かめる風習があります。', 2, false),
(4, 26, '八朔のあいさつ回りで、芸舞妓が掛け合う定番の言葉はどれか。', '「おめでとうさんどす」', '「おたのもうします」', '「おおきにどす」', '「ごきげんよう」', 1, '八朔の日、芸舞妓たちはお茶屋や師匠宅を訪れる際、「おたのもうします（今後ともよろしくお願いいたします）」と挨拶を交わします。', 1, false),
(4, 26, '事始めのあいさつ回りで、芸舞妓が交わす定番の言葉はどれか。', '「おめでとうさんどす」', '「おたのもうします」', '「おいとまします」', '「おきばりやす」', 0, '事始めは「正月を迎える準備の始まり」をお祝いする日でもあるため、「おめでとうさんどす」「相変わりませずおたのもうします」という言葉が交わされます。', 2, false),
(4, 26, '花街における「事納め（ことおさめ）」の日（正月の行事の締めくくり）はいつか。', '12月31日', '1月7日', '1月15日', '1月4日', 3, '花街での始業式や正月行事が一段落する「事納め」や仕事始めは、1月7日前後に行われる始業式などでひと区切りとなります（一般の事納めは2月8日など諸説あります）。', 3, false),
(4, 26, '12月13日の事始めの日に、井上八千代師匠宅で振る舞われる祝儀の食べ物はどれか。', 'お雑煮', 'お祝いの盃・大根煮', '祝膳（祝いの膳）', 'お赤飯', 0, '事始めの日、門下生があいさつに訪れる井上八千代宅では、祝儀としてお雑煮などが用意され、師弟子間の絆を確かめ合います。', 3, false),
(4, 26, '八朔の日に訪問する「お茶屋」の役割として正しいのはどれか。', '煎茶を飲むカフェ', '芸舞妓を呼んで宴会を行う格式高い場', 'お菓子を売る和菓子店', 'お茶の葉を売る専門店', 1, 'お茶屋（おちゃや）は花街において、客が芸妓・舞妓を招いて宴会や接客を受ける格式高い施設です。「一見さんお断り」の伝統を守っている店舗が多く存在します。', 1, false),
(4, 26, '八朔の行事が行われる京都の「五花街（ごかがい）」に含まれないのはどれか。', '祇園甲部', '先斗町', '西陣', '宮川町', 2, '京都の「五花街（ごかがい）」は、祇園甲部・宮川町・先斗町・上七軒・祇園東の5つです。「西陣」は伝統工芸（織物）の街であり、花街ではありません。', 1, false),
(4, 26, '祇園甲部歌舞練場の敷地内にある「八勝館」や師匠宅など、八朔の日に賑わうメインの通りはどこか。', '花見小路通（はなみこうじどおり）', '新京極通', '烏丸通', '千本通', 0, '祇園甲部の中心を通る「花見小路通（はなみこうじどおり）」は、四条通から南へ伸びる石畳の通りで、八朔や事始めの日には多くの芸舞妓が行き交うメインストリートとなります。', 1, false);

